Configure NixOS to enable the audit service by updating the NixOS config, typically stored either in /etc/nixos/configuration.nix or /etc/nixos/flake.nix:

 security.auditd.enable = true;
 security.audit.enable = true;

Rebuild and switch to the new NixOS configuration:
$ sudo nixos-rebuild switch

Configure NixOS to lock an account when three unsuccessful logon attempts occur within 15 minutes.

Update the NixOS config, typically stored either in /etc/nixos/configuration.nix or /etc/nixos/flake.nix, to include the following lines:

 security.pam.services = let pamfile = ''
  auth required pam_faillock.so preauth silent audit deny=3 fail_interval=900 unlock_time=0
  auth sufficient pam_unix.so nullok try_first_pass
  auth [default=die] pam_faillock.so authfail audit deny=3 fail_interval=900 unlock_time=0
  auth sufficient pam_faillock.so authsucc

  account required pam_faillock.so
 '';
 in {
  login.text = pkgs.lib.mkDefault pamfile;
  sshd.text = pkgs.lib.mkDefault pamfile;
 };

Note that the entire pam file must be entered as this pamfile string.

Rebuild and switch to the new NixOS configuration:
$ sudo nixos-rebuild switch

metadata.check_text:
Verify NixOS limits the number of concurrent sessions to 10 for all accounts and/or account types.

Check the pam configuration files and confirm a conf file with maxlogins configured:

$ grep "limits.conf" /etc/pam.d/login
> session required /nix/store/sl3fa5zh61xxl03m64if2wqzbvrb6zly-linux-pam-1.6.1/lib/security/pam_limits.so conf=/nix/store/aq8ni1qh3pdygl9cn3qfb8v583ask67m-limits.conf # limits (order 12200)

$ cat /nix/store/aq8ni1qh3pdygl9cn3qfb8v583ask67m-limits.conf

* hard maxlogins 10
@pipewire - rtprio 95
@pipewire - nice -19
@pipewire - memlock 4194304

If the "maxlogins" item is missing or commented out, or the value is set greater than "10" and is not documented with the information system security officer (ISSO) as an operational requirement, this is a finding.

metadata.fix_text:
Configure NixOS to limit the number of concurrent sessions to 10 for all accounts and/or account types.

Update the NixOS config, typically stored either in /etc/nixos/configuration.nix or /etc/nixos/flake.nix:

security.pam.loginLimits = [
 {
  domain = "*";
  item = "maxlogins";
  type = "hard";
  value = "10";
 }
];

Note: Security.pam.loginLimits can be set as a global domain (with the * wildcard) but may be set differently for multiple domains.

Rebuild and switch to the new NixOS configuration:
$ sudo nixos-rebuild switch

Configure NixOS to initiate a session lock after a 10-minute period of inactivity for graphical user logon.

Update the NixOS config, typically stored either in /etc/nixos/configuration.nix or /etc/nixos/flake.nix:

  programs.dconf.profiles.user.databases = with lib.gvariant; lib.mkBefore [
   {
     settings."org/gnome/desktop/session".idle-delay = (mkUint32 600);
     locks = [ "org/gnome/desktop/session/idle-delay" ];
   }];
 services.logind.extraConfig = ''
   IdleAction = lock
   IdleActionSec = 600
 '';
 services.xserver = {
   displayManager.gdm.wayland = true;
   xautolock = {
     enable = true;
     time = 10;
     locker = "${lib.getExe' config.systemd.package "loginctl"} lock-session";
   };
  };
 };

Rebuild and switch to the new NixOS configuration:
$ sudo nixos-rebuild switch

Configure NixOS to allocate sufficient audit_backlog_limit to capture processes that start prior to the audit daemon.

Add the following Nix code to the NixOS Configuration, usually located in /etc/nixos/configuration.nix or /etc/nixos/flake.nix:

 boot.kernelParams = [
  "audit_backlog_limit=8192"
 ];
security.audit.backlogLimit = 8192;

Rebuild and switch to the new NixOS configuration:
$ sudo nixos-rebuild switch

Configure the operating system to off-load audit records onto a different system or media from the system being audited by specifying a remote destination in the systemd-journald configuration.

On the client, modify /etc/nixos/configuration.nix or /etc/nixos/flake.nix to include the following lines:

services.journald.upload = {
  enable = true;
  Upload = {
     ServerKeyFile = $PATH_TO_CLIENT_PEM_SSL_KEY;
     URL = $URL_OF_REMOTE_SERVER;
     ServerCertificateFile = $PATH_TO_SSL_CERT;
     TrustedCertificateFile = $PATH_TO_SERVER_CERT;
   };
  };
}

On the server, modify /etc/nixos/configuration.nix or /etc/nixos/flake.nix to include the following lines:
services.journald.remote = {
  enable = true;
  listen = "https";
  URL = $URL_OF_REMOTE_SERVER;
  ServerKeyFile = $PATH_TO_SERVER_PEM_SSL_KEY;
  ServerCertificateFile = $PATH_TO_SSL_CERT;
  };
};

Configure the operating system to authenticate the remote logging server for off-loading audit logs.

Add the following Nix code to the NixOS Configuration, usually located in /etc/nixos/configuration.nix or /etc/nixos/flake.nix:

  destination d_network {
   syslog(
    "" port()
    transport(tls)
    tls(
     cert-file("/var/syslog-ng/certs.d/certificate.crt")
     key-file("/var/syslog-ng/certs.d/certificate.key")
     ca-file("/var/syslog-ng/certs.d/cert-bundle.crt")
     peer-verify(yes)
    )
   );
  };

  log { source(s_local); destination(d_local); destination(d_network); };

For example, an updated configuration of 'services.rsyslogd.extraConfig' would look like the following in /etc/nixos/configuration.nix ('...' denoting that the 'services.rsyslogd.extraConfig' configuration may have other options configured):

 services.rsyslogd.extraConfig = ''
   ...
   destination d_network {
    syslog(
     "" port()
     transport(tls)
     tls(
      cert-file("/var/syslog-ng/certs.d/certificate.crt")
      key-file("/var/syslog-ng/certs.d/certificate.key")
      ca-file("/var/syslog-ng/certs.d/cert-bundle.crt")
      peer-verify(yes)
     )
    );
   };

   log { source(s_local); destination(d_local); destination(d_network); };
   ...
  '';

Rebuild and switch to the new NixOS configuration:
$ sudo nixos-rebuild switch

The systemd-journald directories are by design set to 2755 mode.

If any directories are found with incorrect perms, correct them with the following command:

$ sudo find /var/log/journal -type d -exec chmod 2755 {} \;

The systemd-journald files are by design set to 0640 mode.

If any files are found with incorrect perms, correct them with the following command:

$ sudo find /var/log/journal -type f -exec chmod 0640 {} \;

Configure NixOS to authenticate using DOD's root CA.

Add the following Nix code to the NixOS Configuration, usually located in /etc/nixos/configuration.nix or /etc/nixos/flake.nix:

 services.sssd.enable = true;
 environment.etc."sssd/pki/sssd_auth_ca_db.pem".source = let
  certzip = pkgs.fetchzip {
   url = "https://dl.dod.cyber.mil/wp-content/uploads/pki-pke/zip/unclass-certificates_pkcs7_v5-6_dod.zip";
   sha256 = "sha256-iwwJRXCnONk/LFddQlwy8KX9e9kVXW/QWDnX5qZFZjc=";
  };
 in "${certzip}/DOD_PKE_CA_chain.pem";

Rebuild and switch to the new NixOS configuration:
$ sudo nixos-rebuild switch

Configure the audit service to use IPv4 TCP syncookies.

Add the following Nix code to the NixOS Configuration, usually located in /etc/nixos/configuration.nix or /etc/nixos/flake.nix:

boot.kernel.sysctl = {
"net.ipv4.tcp_syncookies"=1;
};

Rebuild and switch to the new NixOS configuration:
$ sudo nixos-rebuild switch

